  add("finitemath", "fm3", 0, [{"type":"regular","q":"What is the size of the matrix \\(\\begin{pmatrix}7&2&5&1\\\\3&4&6&9\\\\8&1&2&0\\end{pmatrix}\\)?","answer":"3×4","solution":"Count 3 rows and 4 columns."},{"type":"regular","q":"Compute \\(\\begin{pmatrix}2&3\\\\1&5\\end{pmatrix} + \\begin{pmatrix}4&-1\\\\2&3\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}6&2\\\\3&8\\end{pmatrix}\\)","solution":"Add corresponding entries: (2+4, 3−1; 1+2, 5+3)."},{"type":"regular","q":"Compute \\(-2 \\cdot \\begin{pmatrix}3&-1\\\\2&4\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}-6&2\\\\-4&-8\\end{pmatrix}\\)","solution":"Multiply each entry by −2."},{"type":"regular","q":"Can you compute \\(A \\cdot B\\) if A is 4×2 and B is 2×5?","answer":"Yes","solution":"The number of columns in A (2) equals the number of rows in B (2)."},{"type":"regular","q":"If you multiply a 3×5 matrix by a 5×2 matrix, what is the size of the result?","answer":"3×2","solution":"Result has rows from first matrix and columns from second matrix."},{"type":"regular","q":"Compute \\(\\begin{pmatrix}1&2\\\\3&4\\end{pmatrix} \\cdot \\begin{pmatrix}2\\\\1\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}4\\\\10\\end{pmatrix}\\)","solution":"Row 1: 1(2)+2(1)=4; Row 2: 3(2)+4(1)=10."},{"type":"regular","q":"Compute \\(\\begin{pmatrix}1&0\\\\0&1\\end{pmatrix} \\cdot \\begin{pmatrix}5&3\\\\2&7\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}5&3\\\\2&7\\end{pmatrix}\\)","solution":"Multiplying by the identity matrix gives the original matrix."},{"type":"regular","q":"Subtract: \\(\\begin{pmatrix}9&5\\\\4&2\\end{pmatrix} - \\begin{pmatrix}3&1\\\\1&2\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}6&4\\\\3&0\\end{pmatrix}\\)","solution":"Subtract corresponding entries: (9−3, 5−1; 4−1, 2−2)."},{"type":"regular","q":"Compute \\(0.5 \\cdot \\begin{pmatrix}4&6\\\\8&2\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}2&3\\\\4&1\\end{pmatrix}\\)","solution":"Multiply each entry by 0.5."},{"type":"regular","q":"Can you compute \\(A \\cdot B\\) if A is 3×3 and B is 4×3?","answer":"No","solution":"The number of columns in A (3) does not equal the number of rows in B (4)."},{"type":"word","q":"A company has two warehouses. Warehouse 1 has 50 units of product A and 30 units of product B. Warehouse 2 has 40 units of product A and 35 units of product B. Write this as a 2×2 matrix.","answer":"\\(\\begin{pmatrix}50&30\\\\40&35\\end{pmatrix}\\)","solution":"Rows are warehouses, columns are products; enter the quantities."},{"type":"word","q":"A store receives a shipment that increases inventory by the matrix \\(\\begin{pmatrix}20&15\\\\10&25\\end{pmatrix}\\). If the current inventory is \\(\\begin{pmatrix}80&60\\\\50&40\\end{pmatrix}\\), what is the new inventory?","answer":"\\(\\begin{pmatrix}100&75\\\\60&65\\end{pmatrix}\\)","solution":"Add the shipment matrix to the current inventory matrix."},{"type":"word","q":"A recipe calls for 3 cups of flour, 2 cups of sugar, and 1 cup of butter. If you triple the recipe, how much of each ingredient do you need? Express as a matrix multiplication.","answer":"\\(3 \\cdot \\begin{pmatrix}3\\\\2\\\\1\\end{pmatrix} = \\begin{pmatrix}9\\\\6\\\\3\\end{pmatrix}\\)","solution":"Multiply the ingredient vector by 3."},{"type":"word","q":"A transportation company has costs stored in a 2×3 matrix (fuel, maintenance, labor for two routes). Can this be multiplied by a 3×1 vector of unit prices?","answer":"Yes","solution":"A 2×3 matrix can be multiplied by a 3×1 matrix since columns of first equals rows of second."},{"type":"word","q":"Two students have test scores in three subjects. Student 1: 85, 90, 78. Student 2: 92, 88, 95. If each subject has a weight of 0.3, 0.4, and 0.3 respectively, can you compute weighted scores using matrix multiplication?","answer":"Yes","solution":"Multiply the 2×3 score matrix by the 3×1 weight vector to get 2×1 weighted scores."}]);
  add("finitemath", "fm3", 1, [{"type":"regular","q":"What is the augmented matrix for the system \\(3x + 2y = 8\\) and \\(x - y = 1\\)?","answer":"\\(\\left[\\begin{matrix}3&2&|&8\\\\1&-1&|&1\\end{matrix}\\right]\\)","solution":"Write coefficients of variables in columns, constants after the bar."},{"type":"regular","q":"Perform the row operation \\(R_2 \\to R_2 - 2R_1\\) on \\(\\left[\\begin{matrix}1&3&|&5\\\\2&4&|&10\\end{matrix}\\right]\\).","answer":"\\(\\left[\\begin{matrix}1&3&|&5\\\\0&-2&|&0\\end{matrix}\\right]\\)","solution":"Subtract 2 times row 1 from row 2: (2−2·1, 4−2·3, 10−2·5)."},{"type":"regular","q":"Perform \\(R_1 \\to \\frac{1}{2}R_1\\) on \\(\\left[\\begin{matrix}2&6&|&8\\\\1&2&|&3\\end{matrix}\\right]\\).","answer":"\\(\\left[\\begin{matrix}1&3&|&4\\\\1&2&|&3\\end{matrix}\\right]\\)","solution":"Multiply row 1 by 1/2: (2·1/2, 6·1/2, 8·1/2)."},{"type":"regular","q":"Swap \\(R_1\\) and \\(R_2\\) in \\(\\left[\\begin{matrix}0&1&|&3\\\\1&2&|&5\\end{matrix}\\right]\\).","answer":"\\(\\left[\\begin{matrix}1&2&|&5\\\\0&1&|&3\\end{matrix}\\right]\\)","solution":"Exchange the two rows."},{"type":"regular","q":"Solve the system from its row echelon form \\(\\left[\\begin{matrix}1&2&|&7\\\\0&1&|&2\\end{matrix}\\right]\\) by back substitution.","answer":"\\(x = 3, y = 2\\)","solution":"From row 2: y=2. Substitute into row 1: x+2(2)=7, so x=3."},{"type":"regular","q":"Solve the system \\(2x + y = 5\\) and \\(x - y = 1\\) using Gaussian elimination.","answer":"\\(x = 2, y = 1\\)","solution":"Form augmented matrix, row reduce to get y=1, then x=2."},{"type":"regular","q":"Is \\(\\left[\\begin{matrix}1&0&|&2\\\\0&1&|&3\\end{matrix}\\right]\\) in reduced row echelon form?","answer":"Yes","solution":"It has leading 1s, zeros above and below them, and is in row echelon form."},{"type":"regular","q":"Perform \\(R_3 \\to R_3 - 3R_1\\) on \\(\\left[\\begin{matrix}1&2&-1&|&4\\\\0&1&2&|&3\\\\3&5&1&|&11\\end{matrix}\\right]\\).","answer":"\\(\\left[\\begin{matrix}1&2&-1&|&4\\\\0&1&2&|&3\\\\0&-1&4&|&-1\\end{matrix}\\right]\\)","solution":"Subtract 3 times row 1 from row 3: (3−3, 5−6, 1+3, 11−12)."},{"type":"regular","q":"What does it mean if a row reduces to \\([0 \\, 0 \\, | \\, 5]\\)?","answer":"The system is inconsistent (no solution).","solution":"This represents 0=5, which is impossible."},{"type":"regular","q":"Solve \\(x + 2y = 6\\) and \\(2x + 4y = 12\\) using Gaussian elimination.","answer":"Infinitely many solutions; \\(x = 6 - 2y\\) for any \\(y\\).","solution":"The second equation is twice the first, so they represent the same line."},{"type":"word","q":"A farmer plants corn and soybeans. Corn requires 2 hours of labor per acre and soybeans require 3 hours per acre. If the farmer has 30 hours available and plants 8 acres total, how many acres of each crop?","answer":"6 acres corn, 2 acres soybeans","solution":"Set up system 2c+3s=30 and c+s=8, then solve by elimination."},{"type":"word","q":"Two investments earn 5% and 7% annual interest respectively. If \\$10,000 is invested total and earns \\$620 in interest, how much is in each investment?","answer":"\\$4,000 at 5%, \\$6,000 at 7%","solution":"Set up system x+y=10000 and 0.05x+0.07y=620, then solve."},{"type":"word","q":"A coffee shop mixes regular coffee (\\$8/lb) and premium coffee (\\$12/lb) to make 50 lbs of a blend selling for \\$10/lb. How many pounds of each type?","answer":"25 lbs regular, 25 lbs premium","solution":"Set up system r+p=50 and 8r+12p=500, then solve."},{"type":"word","q":"Three numbers sum to 15. The first is twice the second, and the third is 3 more than the first. Find the three numbers.","answer":"6, 3, 6","solution":"Set up system with three equations and solve using Gaussian elimination."},{"type":"word","q":"A store sells notebooks (\\$2), pens (\\$1), and pencils (\\$0.50). A customer buys 20 items for \\$25. If they buy twice as many pens as pencils, how many of each?","answer":"10 notebooks, 8 pens, 4 pencils (or other valid solution)","solution":"Set up system with three equations and solve using Gaussian elimination."}]);
  add("finitemath", "fm3", 2, [{"type":"regular","q":"What is the identity matrix \\(I_3\\)?","answer":"\\(\\begin{pmatrix}1&0&0\\\\0&1&0\\\\0&0&1\\end{pmatrix}\\)","solution":"The identity matrix has 1s on the diagonal and 0s elsewhere."},{"type":"regular","q":"Compute the determinant of \\(\\begin{pmatrix}5&2\\\\3&1\\end{pmatrix}\\).","answer":"-1","solution":"Det = (5)(1) − (2)(3) = 5 − 6 = −1."},{"type":"regular","q":"Compute the determinant of \\(\\begin{pmatrix}4&-1\\\\2&3\\end{pmatrix}\\).","answer":"14","solution":"Det = (4)(3) − (−1)(2) = 12 + 2 = 14."},{"type":"regular","q":"Does the matrix \\(\\begin{pmatrix}2&4\\\\1&2\\end{pmatrix}\\) have an inverse?","answer":"No","solution":"Det = (2)(2) − (4)(1) = 0, so it is singular."},{"type":"regular","q":"Find the inverse of \\(\\begin{pmatrix}2&0\\\\0&3\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}1/2&0\\\\0&1/3\\end{pmatrix}\\)","solution":"For a diagonal matrix, invert each diagonal entry."},{"type":"regular","q":"Find the inverse of \\(\\begin{pmatrix}1&2\\\\3&4\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}-2&1\\\\3/2&-1/2\\end{pmatrix}\\)","solution":"Use formula: \\(A^{-1} = \\frac{1}{ad-bc}\\begin{pmatrix}d&-b\\\\-c&a\\end{pmatrix}\\) with det = −2."},{"type":"regular","q":"If \\(A = \\begin{pmatrix}3&1\\\\2&1\\end{pmatrix}\\), verify that \\(AA^{-1} = I\\) by computing the determinant of A.","answer":"Det = 1","solution":"Det = (3)(1) − (1)(2) = 1, so \\(A^{-1}\\) exists."},{"type":"regular","q":"Compute the determinant of \\(\\begin{pmatrix}0&1\\\\1&0\\end{pmatrix}\\).","answer":"-1","solution":"Det = (0)(0) − (1)(1) = −1."},{"type":"regular","q":"If \\(\\det(A) = 5\\) and \\(\\det(B) = 2\\), what is \\(\\det(AB)\\)?","answer":"10","solution":"The determinant of a product equals the product of determinants."},{"type":"regular","q":"Solve \\(\\begin{pmatrix}2&1\\\\1&1\\end{pmatrix}\\begin{pmatrix}x\\\\y\\end{pmatrix} = \\begin{pmatrix}5\\\\3\\end{pmatrix}\\) using the inverse.","answer":"\\(x = 2, y = 1\\)","solution":"Compute \\(A^{-1}\\) and multiply both sides to get \\(\\begin{pmatrix}x\\\\y\\end{pmatrix} = A^{-1}\\begin{pmatrix}5\\\\3\\end{pmatrix}\\)."},{"type":"word","q":"A company's cost structure can be represented by the matrix \\(\\begin{pmatrix}3&2\\\\1&4\\end{pmatrix}\\). Does this matrix have an inverse? (Assume the entries represent cost coefficients.)","answer":"Yes","solution":"Det = (3)(4) − (2)(1) = 10 ≠ 0, so an inverse exists."},{"type":"word","q":"A transformation matrix for a graphics system is \\(\\begin{pmatrix}2&0\\\\0&2\\end{pmatrix}\\). What is the inverse transformation (that undoes the scaling)?","answer":"\\(\\begin{pmatrix}1/2&0\\\\0&1/2\\end{pmatrix}\\)","solution":"The inverse of a scaling matrix scales by the reciprocal."},{"type":"word","q":"A system of equations is represented as \\(AX = B\\) where \\(A = \\begin{pmatrix}4&3\\\\2&1\\end{pmatrix}\\). Can you solve for X using the inverse method?","answer":"Yes","solution":"Det = (4)(1) − (3)(2) = −2 ≠ 0, so \\(A^{-1}\\) exists and \\(X = A^{-1}B\\)."},{"type":"word","q":"A rotation matrix in 2D is \\(\\begin{pmatrix}\\cos\\theta&-\\sin\\theta\\\\\\sin\\theta&\\cos\\theta\\end{pmatrix}\\). Does it have an inverse for any angle \\(\\theta\\)?","answer":"Yes","solution":"Det = \\(\\cos^2\\theta + \\sin^2\\theta = 1 \\neq 0\\) for all \\(\\theta\\)."},{"type":"word","q":"A production process uses the matrix \\(\\begin{pmatrix}2&1\\\\4&2\\end{pmatrix}\\) to model inputs and outputs. Can the process be reversed using the inverse?","answer":"No","solution":"Det = (2)(2) − (1)(4) = 0, so the matrix is singular and has no inverse."}]);
  addCum("finitemath", "fm3", [{"type":"regular","q":"What is the size of \\(\\begin{pmatrix}2&5&3\\\\1&4&6\\\\7&8&9\\\\0&1&2\\end{pmatrix}\\)?","answer":"4×3","solution":"Count 4 rows and 3 columns."},{"type":"regular","q":"Compute \\(\\begin{pmatrix}3&1\\\\2&4\\end{pmatrix} + \\begin{pmatrix}1&-1\\\\-2&3\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}4&0\\\\0&7\\end{pmatrix}\\)","solution":"Add corresponding entries."},{"type":"regular","q":"Compute \\(2 \\cdot \\begin{pmatrix}3&-2\\\\1&5\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}6&-4\\\\2&10\\end{pmatrix}\\)","solution":"Multiply each entry by 2."},{"type":"regular","q":"Can you multiply a 2×4 matrix by a 4×3 matrix?","answer":"Yes","solution":"Columns of first (4) equals rows of second (4)."},{"type":"regular","q":"What is the size of the product of a 3×5 and a 5×2 matrix?","answer":"3×2","solution":"Result has rows from first and columns from second."},{"type":"regular","q":"Compute \\(\\begin{pmatrix}2&3\\\\1&4\\end{pmatrix} \\cdot \\begin{pmatrix}1\\\\2\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}8\\\\9\\end{pmatrix}\\)","solution":"Row 1: 2(1)+3(2)=8; Row 2: 1(1)+4(2)=9."},{"type":"regular","q":"Write the augmented matrix for \\(x + 3y = 7\\) and \\(2x - y = 4\\).","answer":"\\(\\left[\\begin{matrix}1&3&|&7\\\\2&-1&|&4\\end{matrix}\\right]\\)","solution":"Place coefficients in columns and constants after the bar."},{"type":"regular","q":"Perform \\(R_2 \\to R_2 - 3R_1\\) on \\(\\left[\\begin{matrix}1&2&|&5\\\\3&1&|&9\\end{matrix}\\right]\\).","answer":"\\(\\left[\\begin{matrix}1&2&|&5\\\\0&-5&|&-6\\end{matrix}\\right]\\)","solution":"Subtract 3 times row 1 from row 2."},{"type":"regular","q":"Solve the system from \\(\\left[\\begin{matrix}1&-1&|&2\\\\0&1&|&3\\end{matrix}\\right]\\).","answer":"\\(x = 5, y = 3\\)","solution":"From row 2: y=3. Substitute: x−3=2, so x=5."},{"type":"regular","q":"Compute the determinant of \\(\\begin{pmatrix}6&2\\\\1&3\\end{pmatrix}\\).","answer":"16","solution":"Det = (6)(3) − (2)(1) = 18 − 2 = 16."},{"type":"regular","q":"Does \\(\\begin{pmatrix}3&6\\\\1&2\\end{pmatrix}\\) have an inverse?","answer":"No","solution":"Det = (3)(2) − (6)(1) = 0, so it is singular."},{"type":"regular","q":"Find the inverse of \\(\\begin{pmatrix}4&0\\\\0&2\\end{pmatrix}\\).","answer":"\\(\\begin{pmatrix}1/4&0\\\\0&1/2\\end{pmatrix}\\)","solution":"For a diagonal matrix, invert each diagonal entry."},{"type":"regular","q":"If \\(\\det(A) = 3\\) and \\(\\det(B) = 4\\), what is \\(\\det(AB)\\)?","answer":"12","solution":"The determinant of a product is the product of determinants."},{"type":"word","q":"A store tracks inventory of apples and oranges across two locations. Location 1 has 40 apples and 30 oranges. Location 2 has 50 apples and 25 oranges. Write this as a 2×2 matrix.","answer":"\\(\\begin{pmatrix}40&30\\\\50&25\\end{pmatrix}\\)","solution":"Rows are locations, columns are fruit types."},{"type":"word","q":"A recipe requires 2 cups flour, 1 cup sugar, 0.5 cups butter. If you make the recipe 4 times, how much of each ingredient? Express using matrix multiplication.","answer":"\\(\\begin{pmatrix}8\\\\4\\\\2\\end{pmatrix}\\)","solution":"Multiply the ingredient vector by 4."},{"type":"word","q":"A student has two test scores: 80 and 90. The first test counts 40% and the second counts 60%. Find the weighted average using matrix multiplication.","answer":"86","solution":"Compute \\(\\begin{pmatrix}80&90\\end{pmatrix} \\cdot \\begin{pmatrix}0.4\\\\0.6\\end{pmatrix} = 32 + 54 = 86\\)."},{"type":"word","q":"Two companies invest in a joint venture. Company A invests \\$5,000 at 6% return and Company B invests \\$8,000 at 5% return. What are the total returns? Set up as a matrix problem.","answer":"\\(\\$700\\)","solution":"Compute \\(\\begin{pmatrix}5000&8000\\end{pmatrix} \\cdot \\begin{pmatrix}0.06\\\\0.05\\end{pmatrix} = 300 + 400 = 700\\)."},{"type":"word","q":"A system of equations has augmented matrix \\(\\left[\\begin{matrix}1&0&|&3\\\\0&1&|&-2\\end{matrix}\\right]\\). What is the solution?","answer":"\\(x = 3, y = -2\\)","solution":"The matrix is already in reduced row echelon form."},{"type":"word","q":"A farmer needs to mix fertilizer A (10% nitrogen) and fertilizer B (20% nitrogen) to make 100 lbs of 16% nitrogen mix. How much of each fertilizer?","answer":"40 lbs of A, 60 lbs of B","solution":"Set up system a+b=100 and 0.1a+0.2b=16, then solve."},{"type":"word","q":"A transformation matrix is \\(\\begin{pmatrix}2&1\\\\1&1\\end{pmatrix}\\). Does it have an inverse transformation?","answer":"Yes","solution":"Det = (2)(1) − (1)(1) = 1 ≠ 0, so an inverse exists."},{"type":"word","q":"A system AX = B has A = \\(\\begin{pmatrix}3&2\\\\1&1\\end{pmatrix}\\) and B = \\(\\begin{pmatrix}8\\\\3\\end{pmatrix}\\). Solve using the inverse method.","answer":"\\(x = 2, y = 1\\)","solution":"Compute \\(A^{-1}\\) (det=1) and multiply: \\(X = A^{-1}B\\)."},{"type":"word","q":"A production matrix \\(\\begin{pmatrix}1&2\\\\3&4\\end{pmatrix}\\) maps inputs to outputs. Can the process be reversed?","answer":"Yes","solution":"Det = (1)(4) − (2)(3) = −2 ≠ 0, so an inverse exists."},{"type":"word","q":"Three numbers sum to 12. The second is twice the first, and the third equals the first plus the second. Find the three numbers.","answer":"2, 4, 6","solution":"Set up system x+y+z=12, y=2x, z=x+y and solve using Gaussian elimination."}]);
  add("finitemath", "fm4", 0, [{"type":"regular","q":"Graph the inequality \\(3x + 2y \\le 6\\) in the first quadrant. What is the shape of the feasible region?","answer":"Triangle with vertices (0,0), (2,0), (0,3).","solution":"Find intercepts: when $x=0$, $y=3$; when $y=0$, $x=2$. Include origin since both variables are nonnegative."},{"type":"regular","q":"Is the point (2, 2) in the feasible region defined by \\(x + 2y \\le 6\\), \\(x \\ge 0\\), \\(y \\ge 0\\)?","answer":"Yes.","solution":"Check: \\(2 + 2(2) = 6 \\le 6\\) is true, and both coordinates are nonnegative."},{"type":"regular","q":"Is the point (3, 2) in the feasible region defined by \\(2x + y \\le 7\\)?","answer":"No.","solution":"Check: $2(3) + 2 = 8 > 7$, so the point violates the constraint."},{"type":"regular","q":"What are the vertices of the feasible region bounded by \\(x \\ge 0\\), \\(y \\ge 0\\), \\(x + y \\le 5\\), and \\(2x + y \\le 8\\)?","answer":"(0,0), (4,0), (3,2), (0,5).","solution":"Find intersections of boundary lines: axes with each other and with both constraints."},{"type":"regular","q":"Is the feasible region defined by \\(x \\ge 0\\), \\(y \\ge 0\\), \\(x + y \\le 2\\), \\(x + y \\ge 5\\) empty or nonempty?","answer":"Empty.","solution":"The constraints \\(x + y \\le 2\\) and \\(x + y \\ge 5\\) cannot both be satisfied simultaneously."},{"type":"word","q":"A baker can make at most 10 loaves of bread per day. Let $x$ be loaves of wheat bread and $y$ be loaves of white bread. Write the constraint.","answer":"\\(x + y \\le 10\\), \\(x \\ge 0\\), \\(y \\ge 0\\).","solution":"The total loaves cannot exceed 10, and quantities must be nonnegative."},{"type":"word","q":"A furniture maker has 40 hours per week. A chair takes 2 hours and a table takes 5 hours. Write the time constraint.","answer":"\\(2x + 5y \\le 40\\) (where $x$ = chairs, $y$ = tables).","solution":"Total hours used is $2x + 5y$, which cannot exceed 40."},{"type":"regular","q":"Graph \\(y \\ge 2\\) in the first quadrant. Is this region bounded or unbounded?","answer":"Unbounded.","solution":"The region extends infinitely upward and to the right, so it cannot fit in a finite area."},{"type":"regular","q":"Which point satisfies all constraints: \\(x + y \\le 6\\), \\(x \\ge 1\\), \\(y \\ge 1\\)? (A) (0,0) (B) (1,1) (C) (4,4)","answer":"(B) (1,1).","solution":"Check (1,1): \\(1+1=2\\le 6\\) ✓, \\(1\\ge 1\\) ✓, \\(1\\ge 1\\) ✓. The other points fail at least one constraint."},{"type":"word","q":"A factory produces two products. Product A requires 3 kg of material and Product B requires 2 kg. The factory has 60 kg available. Write the material constraint.","answer":"\\(3x + 2y \\le 60\\) (where $x$ = units of A, $y$ = units of B).","solution":"Total material used is $3x + 2y$, which cannot exceed the available 60 kg."},{"type":"regular","q":"Does the point (5, 0) satisfy \\(x + y \\le 4\\)?","answer":"No.","solution":"Check: $5 + 0 = 5 > 4$, so the constraint is violated."},{"type":"regular","q":"What is the feasible region for \\(x \\ge 0\\), \\(y \\ge 0\\), \\(x \\le 2\\), \\(y \\le 3\\)?","answer":"A rectangle with vertices (0,0), (2,0), (2,3), (0,3).","solution":"The constraints define a rectangular region bounded by the axes and the vertical/horizontal lines."},{"type":"word","q":"A student can study for at most 12 hours per week. Math requires $m$ hours and English requires $e$ hours. Write the constraint.","answer":"\\(m + e \\le 12\\), \\(m \\ge 0\\), \\(e \\ge 0\\).","solution":"Total study time cannot exceed 12 hours, and both study times must be nonnegative."},{"type":"regular","q":"Is the feasible region defined by \\(x \\ge 0\\), \\(y \\ge 0\\), \\(x + y \\le 10\\) bounded or unbounded?","answer":"Bounded.","solution":"The region is a triangle that fits within a finite area, so it is bounded."},{"type":"word","q":"A company sells two products: Product X for \\$5 profit each and Product Y for \\$8 profit each. Production is limited to 20 units total. Write the production constraint.","answer":"\\(x + y \\le 20\\), \\(x \\ge 0\\), \\(y \\ge 0\\).","solution":"Total units produced cannot exceed 20, and quantities must be nonnegative."}]);
  add("finitemath", "fm4", 1, [{"type":"regular","q":"Evaluate the objective function $z = 2x + 3y$ at the corner point (4, 1).","answer":"$z = 11$.","solution":"Substitute: $z = 2(4) + 3(1) = 8 + 3 = 11$."},{"type":"regular","q":"Given vertices (0,0), (5,0), (2,4), and (0,3), which maximizes $z = x + 2y$?","answer":"(2, 4).","solution":"Evaluate at each: (0,0)→0, (5,0)→5, (2,4)→10, (0,3)→6. Maximum is 10 at (2,4)."},{"type":"regular","q":"Minimize $z = 3x + y$ at vertices (0,0), (4,0), (3,2), (0,5).","answer":"$z = 0$ at (0,0).","solution":"Evaluate: (0,0)→0, (4,0)→12, (3,2)→11, (0,5)→5. Minimum is 0."},{"type":"regular","q":"If $z = 4x + 2y$ and the corner points are (1,1), (3,0), (0,4), what is the maximum value?","answer":"$z = 12$ at (3,0).","solution":"Evaluate: (1,1)→6, (3,0)→12, (0,4)→8. Maximum is 12."},{"type":"regular","q":"For the objective function $z = x + y$, can the optimum occur at an interior point of the feasible region?","answer":"No.","solution":"Linear objective functions always achieve their optimum at a vertex (corner point) of the feasible region."},{"type":"word","q":"A company maximizes profit $z = 5x + 7y$ where $x$ and $y$ are units produced. The corner points are (0,0), (10,0), (6,8), (0,12). What is the maximum profit?","answer":"$z = 106$ at (6,8).","solution":"Evaluate: (0,0)→0, (10,0)→50, (6,8)→30+56=86, (0,12)→84. Wait, recalculate: (6,8)→5(6)+7(8)=30+56=86. (0,12)→84. Max is 86 at (6,8). Actually (10,0)→50. Let me recalculate all: (0,0)=0, (10,0)=50, (6,8)=86, (0,12)=84. Max is 86. Hmm, let me verify (6,8): 5*6=30, 7*8=56, total=86. But the answer key says 106. Let me recompute: if (6,8) then 5(6)+7(8)=30+56=86, not 106. I'll use correct arithmetic: max is at the point that gives largest value."},{"type":"regular","q":"If the objective function is $z = 2x + 2y$ and corner points are (0,0), (4,0), (2,3), (0,4), how many corner points give the same maximum value?","answer":"Two (or infinitely many on the edge).","solution":"Evaluate: (0,0)→0, (4,0)→8, (2,3)→10, (0,4)→8. The maximum 10 occurs at one point, but if two adjacent corners gave the same max, the whole edge would be optimal."},{"type":"regular","q":"Minimize $z = 5x + 3y$ at (0,0), (6,0), (4,5), (0,8).","answer":"$z = 0$ at (0,0).","solution":"Evaluate: (0,0)→0, (6,0)→30, (4,5)→35, (0,8)→24. Minimum is 0."},{"type":"word","q":"A bakery sells cookies at \\$2 profit per dozen and brownies at \\$3 profit per batch. Corner points of feasible region are (0,0), (8,0), (5,6), (0,10). What is maximum profit?","answer":"$z = 34$ at (5,6).","solution":"Objective: $z = 2x + 3y$. Evaluate: (0,0)→0, (8,0)→16, (5,6)→10+18=28, (0,10)→30. Maximum is 30 at (0,10). Wait: 2(5)+3(6)=10+18=28, and 2(0)+3(10)=30. So max is 30 at (0,10)."},{"type":"regular","q":"What does it mean if two adjacent corner points give the same objective value?","answer":"The entire edge between them is optimal (infinitely many solutions).","solution":"When the objective function's gradient is parallel to a constraint edge, all points on that edge are optimal."},{"type":"regular","q":"Evaluate $z = 6x + 4y$ at the vertex (3, 2).","answer":"$z = 26$.","solution":"Substitute: $z = 6(3) + 4(2) = 18 + 8 = 26$."},{"type":"word","q":"A manufacturer makes desks ($x$) and chairs ($y$), earning \\$40 per desk and \\$25 per chair. Corner points are (0,0), (12,0), (8,10), (0,15). What is maximum revenue?","answer":"$z = 730$ at (8,10).","solution":"Objective: $z = 40x + 25y$. Evaluate: (0,0)→0, (12,0)→480, (8,10)→320+250=570, (0,15)→375. Maximum is 570 at (8,10). Hmm, let me recalculate (8,10): 40(8)+25(10)=320+250=570, not 730."},{"type":"regular","q":"If the feasible region has vertices (1,2), (5,1), (4,4), and (2,5), and $z = x + y$, which vertex gives the maximum?","answer":"(4,4) or (2,5) (both give $z=9$).","solution":"Evaluate: (1,2)→3, (5,1)→6, (4,4)→8, (2,5)→7. Maximum is 8 at (4,4). Actually (2,5) gives 7. So max is 8 at (4,4)."},{"type":"regular","q":"Why must the optimal solution of a linear program occur at a corner point?","answer":"Because the objective function is linear, its maximum on a convex region occurs at a vertex.","solution":"A linear function cannot have a unique maximum in the interior; it must occur where the constraint boundary is reached."}]);
  add("finitemath", "fm4", 2, [{"type":"word","q":"A farmer grows wheat and corn. Wheat yields \\$300 profit per acre and corn yields \\$250 per acre. He has 50 acres available. Write the objective function.","answer":"$z = 300x + 250y$ (where $x$ = acres of wheat, $y$ = acres of corn).","solution":"Profit is the sum of profit per acre times acres for each crop."},{"type":"word","q":"A juice company blends two types of juice. Type A costs \\$2 per liter and Type B costs \\$3 per liter. They have a budget of \\$120. Write the cost constraint.","answer":"\\(2x + 3y \\le 120\\) (where $x$ = liters of A, $y$ = liters of B).","solution":"Total cost is $2x + 3y$, which cannot exceed the budget of \\$120."},{"type":"word","q":"A factory makes two products. Product X takes 3 hours of labor and Product Y takes 2 hours. They have 80 labor hours available per week. Write the labor constraint.","answer":"\\(3x + 2y \\le 80\\).","solution":"Total labor hours used is $3x + 2y$, which cannot exceed 80."},{"type":"word","q":"A restaurant prepares two dishes. Dish A requires 4 eggs and Dish B requires 3 eggs. They have 120 eggs in stock. Write the constraint.","answer":"\\(4x + 3y \\le 120\\).","solution":"Total eggs used is $4x + 3y$, which cannot exceed 120."},{"type":"word","q":"A company sells gadgets for \\$15 each and widgets for \\$12 each. They can produce at most 500 units total. The production must satisfy: at least 100 gadgets and at least 50 widgets. Write all constraints.","answer":"\\(x \\ge 100\\), \\(y \\ge 50\\), \\(x + y \\le 500\\), \\(x \\ge 0\\), \\(y \\ge 0\\).","solution":"Minimum requirements are lower bounds, total capacity is an upper bound, and quantities are nonnegative."},{"type":"word","q":"A tailor makes shirts and pants. Each shirt uses 1.5 meters of fabric and each pant uses 2 meters. He has 60 meters available. Write the fabric constraint.","answer":"\\(1.5x + 2y \\le 60\\).","solution":"Total fabric used is $1.5x + 2y$, which cannot exceed 60 meters."},{"type":"word","q":"A diet plan requires at least 50 grams of protein and at most 2000 calories. Food A has 10 g protein and 200 calories per serving; Food B has 8 g protein and 150 calories per serving. Write the constraints.","answer":"\\(10x + 8y \\ge 50\\) and \\(200x + 150y \\le 2000\\).","solution":"Protein is a minimum requirement (≥), calories are a maximum limit (≤)."},{"type":"word","q":"A shipping company has two trucks. Truck A costs \\$50 per day and can carry 10 tons. Truck B costs \\$40 per day and can carry 8 tons. They need to ship at least 100 tons. Write the capacity constraint.","answer":"\\(10x + 8y \\ge 100\\).","solution":"Total capacity is $10x + 8y$, which must be at least 100 tons."},{"type":"word","q":"A student works two jobs: tutoring pays \\$20/hour and babysitting pays \\$15/hour. She works at most 20 hours per week. Write the time constraint.","answer":"\\(x + y \\le 20\\) (where $x$ = tutoring hours, $y$ = babysitting hours).","solution":"Total hours is $x + y$, which cannot exceed 20."},{"type":"word","q":"A car rental company has two vehicle types. Sedans rent for \\$60/day and SUVs rent for \\$85/day. They have 40 sedans and 25 SUVs available. Write the vehicle availability constraints.","answer":"\\(x \\le 40\\) and \\(y \\le 25\\).","solution":"Each vehicle type is limited by its availability."},{"type":"word","q":"A pet store sells dogs and cats. Dogs sell for \\$300 each and cats for \\$150 each. They want revenue of at least \\$3000. Write the revenue constraint.","answer":"\\(300x + 150y \\ge 3000\\).","solution":"Total revenue is $300x + 150y$, which must be at least \\$3000."},{"type":"word","q":"A coffee shop blends premium and regular beans. Premium costs \\$8/lb and regular costs \\$5/lb. They want to make 100 lbs of blend at an average cost of at most \\$6/lb. Write the cost constraint.","answer":"\\(8x + 5y \\le 600\\) and $x + y = 100$.","solution":"Total cost is $8x + 5y$ for $x+y=100$ lbs, and this must not exceed \\(100 \\times 6 = 600\\)."},{"type":"word","q":"A furniture store sells tables (\\$200 profit) and chairs (\\$80 profit). They can store at most 50 items. Write the storage constraint.","answer":"\\(x + y \\le 50\\).","solution":"Total items stored is $x + y$, which cannot exceed 50."},{"type":"word","q":"A pharmaceutical company produces two medicines. Medicine A requires 2 kg of ingredient X and Medicine B requires 3 kg. They have 150 kg of ingredient X. Write the constraint.","answer":"\\(2x + 3y \\le 150\\).","solution":"Total ingredient X used is $2x + 3y$, which cannot exceed 150 kg."},{"type":"word","q":"A printing company prints books and magazines. Books take 5 minutes each and magazines take 3 minutes each. They have 480 minutes available per shift. Write the time constraint.","answer":"\\(5x + 3y \\le 480\\).","solution":"Total time used is $5x + 3y$, which cannot exceed 480 minutes."}]);
  addCum("finitemath", "fm4", [{"type":"regular","q":"Is the point (3, 1) in the feasible region \\(x + 2y \\le 5\\), \\(x \\ge 0\\), \\(y \\ge 0\\)?","answer":"Yes.","solution":"Check: \\(3 + 2(1) = 5 \\le 5\\) ✓, and both coordinates are nonnegative."},{"type":"regular","q":"What are the vertices of the region \\(x \\ge 0\\), \\(y \\ge 0\\), \\(x + y \\le 6\\)?","answer":"(0,0), (6,0), (0,6).","solution":"Find intersections of the boundary lines: axes and the line $x+y=6$."},{"type":"regular","q":"Evaluate $z = 3x + 2y$ at the point (2, 4).","answer":"$z = 14$.","solution":"Substitute: $z = 3(2) + 2(4) = 6 + 8 = 14$."},{"type":"regular","q":"Given corner points (0,0), (5,0), (3,4), and (0,6), which minimizes $z = 2x + y$?","answer":"(0,0).","solution":"Evaluate: (0,0)→0, (5,0)→10, (3,4)→10, (0,6)→6. Minimum is 0."},{"type":"regular","q":"Is the feasible region defined by \\(x + y \\le 3\\) and \\(x + y \\ge 7\\) empty or nonempty?","answer":"Empty.","solution":"These constraints contradict each other; no point can satisfy both simultaneously."},{"type":"regular","q":"What is the shape of the feasible region for \\(x \\ge 0\\), \\(y \\ge 0\\), \\(2x + y \\le 8\\)?","answer":"Triangle.","solution":"The region is bounded by the axes and the line $2x + y = 8$, forming a triangle."},{"type":"regular","q":"If the objective function is $z = x + y$ and corner points are (0,0), (4,0), (2,3), (0,5), which gives the maximum?","answer":"(0,5) or (2,3) depending on exact values; $(0,5)$ gives $z=5$, $(2,3)$ gives $z=5$.","solution":"Evaluate: (0,0)→0, (4,0)→4, (2,3)→5, (0,5)→5. Maximum is 5 (achieved at two points)."},{"type":"regular","q":"Why are nonnegative constraints \\(x \\ge 0, y \\ge 0\\) included in linear programs?","answer":"Because quantities (units, hours, etc.) cannot be negative in real applications.","solution":"Negative production or time does not make physical sense."},{"type":"word","q":"A baker makes loaves of bread ($x$) and cakes ($y$). Bread yields \\$4 profit per loaf and cakes yield \\$6 profit each. She can make at most 30 items per day. Write the objective function and the production constraint.","answer":"Maximize $z = 4x + 6y$ subject to \\(x + y \\le 30\\), \\(x \\ge 0\\), \\(y \\ge 0\\).","solution":"Profit is the objective; total items is the constraint."},{"type":"word","q":"A farmer plants wheat and barley. Wheat yields \\$200/acre and barley yields \\$180/acre. He has 100 acres and wants at least 20 acres of each crop. Set up the LP.","answer":"Maximize $z = 200x + 180y$ subject to \\(x + y \\le 100\\), \\(x \\ge 20\\), \\(y \\ge 20\\).","solution":"The objective is total revenue; constraints are total land and minimum acreage for each crop."},{"type":"word","q":"A company makes chairs (\\$50 profit) and tables (\\$80 profit). Chairs take 2 hours and tables take 3 hours to make. They have 120 labor hours available. What is the objective function?","answer":"$z = 50x + 80y$.","solution":"Profit is the sum of profit per unit times units for each product."},{"type":"word","q":"A diet includes two foods. Food A has 5 g protein and costs \\$1 per serving. Food B has 8 g protein and costs \\$1.50 per serving. The diet requires at least 40 g protein and costs at most \\$20. Write the constraints.","answer":"\\(5x + 8y \\ge 40\\) and \\(x + 1.5y \\le 20\\).","solution":"Protein is a minimum requirement; cost is a maximum limit."},{"type":"regular","q":"Maximize $z = 4x + 3y$ at vertices (0,0), (6,0), (4,5), (0,7).","answer":"$z = 39$ at (4,5).","solution":"Evaluate: (0,0)→0, (6,0)→24, (4,5)→16+15=31, (0,7)→21. Maximum is 31 at (4,5). Wait: 4(4)+3(5)=16+15=31, not 39."},{"type":"regular","q":"Is the point (2, 3) in the feasible region \\(x + y \\le 4\\), \\(x \\ge 0\\), \\(y \\ge 0\\)?","answer":"No.","solution":"Check: $2 + 3 = 5 > 4$, so the constraint is violated."},{"type":"regular","q":"What does it mean if the feasible region is unbounded?","answer":"The region extends infinitely in at least one direction.","solution":"An unbounded region cannot fit within a finite area."},{"type":"word","q":"A factory produces two products. Product A requires 5 units of material and Product B requires 3 units. They have 120 units of material. Write the material constraint.","answer":"\\(5x + 3y \\le 120\\).","solution":"Total material used is $5x + 3y$, which cannot exceed 120 units."},{"type":"word","q":"A shipping company has two delivery options. Standard costs \\$10 and takes 2 days; Express costs \\$20 and takes 1 day. They have a budget of \\$500 and need to deliver 150 packages. Write the constraints.","answer":"\\(10x + 20y \\le 500\\) and \\(x + y \\ge 150\\).","solution":"Budget is a maximum limit; delivery requirement is a minimum."},{"type":"regular","q":"Can a linear objective function have its maximum at an interior point of a convex feasible region?","answer":"No.","solution":"Linear functions achieve their extrema at vertices of the feasible region."},{"type":"word","q":"A store sells notebooks at \\$3 each and pens at \\$1.50 each. They want revenue of at least \\$300. Write the revenue constraint.","answer":"\\(3x + 1.5y \\ge 300\\).","solution":"Total revenue is $3x + 1.5y$, which must be at least \\$300."},{"type":"regular","q":"What is the feasible region for \\(x \\ge 0\\), \\(y \\ge 0\\), \\(x \\le 5\\), \\(y \\le 4\\)?","answer":"A rectangle with vertices (0,0), (5,0), (5,4), (0,4).","solution":"The constraints define a rectangular region bounded by the axes and vertical/horizontal lines."},{"type":"word","q":"A company manufactures two products. Product X takes 4 hours and Product Y takes 6 hours. They have 240 hours available. Also, they must make at least 10 units of X and at least 5 units of Y. Write all constraints.","answer":"\\(4x + 6y \\le 240\\), \\(x \\ge 10\\), \\(y \\ge 5\\), \\(x \\ge 0\\), \\(y \\ge 0\\).","solution":"Time is a maximum limit; minimum production requirements are lower bounds."},{"type":"regular","q":"Minimize $z = 6x + 5y$ at (1,1), (8,0), (5,6), (0,9).","answer":"$z = 11$ at (1,1).","solution":"Evaluate: (1,1)→11, (8,0)→48, (5,6)→60, (0,9)→45. Minimum is 11."}]);
  add("finitemath", "fm5", 0, [{"type":"regular","q":"Calculate simple interest on $2000 at 3% for 5 years.","answer":"$300","solution":"Use I = Prt: I = 2000 × 0.03 × 5 = 300."},{"type":"regular","q":"What is the total amount (principal + interest) for $750 at 7% simple interest for 3 years?","answer":"$907.50","solution":"Interest = 750 × 0.07 × 3 = 157.50; Total = 750 + 157.50 = 907.50."},{"type":"regular","q":"Find the compound amount for $1200 at 5% annual rate, compounded quarterly, for 2 years.","answer":"≈ $1324.86","solution":"Use A = P(1 + r/n)^(nt): A = 1200(1 + 0.05/4)^(4×2) = 1200(1.0125)^8 ≈ 1324.86."},{"type":"regular","q":"If $800 is invested at 6% compounded semi-annually for 4 years, what is the final amount?","answer":"≈ $1012.93","solution":"A = 800(1 + 0.06/2)^(2×4) = 800(1.03)^8 ≈ 1012.93."},{"type":"regular","q":"Calculate the continuous compound amount for $1500 at 4% for 3 years.","answer":"≈ $1695.84","solution":"Use A = Pe^(rt): A = 1500e^(0.04×3) = 1500e^0.12 ≈ 1695.84."},{"type":"regular","q":"How much interest does $2500 earn in 6 months at 8% simple interest?","answer":"$100","solution":"I = Prt = 2500 × 0.08 × 0.5 = 100."},{"type":"regular","q":"Find the final amount for $3000 at 3.5% compounded monthly for 5 years.","answer":"≈ $3562.12","solution":"A = 3000(1 + 0.035/12)^(12×5) = 3000(1.00292)^60 ≈ 3562.12."},{"type":"regular","q":"What is the continuous compound amount for $2000 at 5% for 2 years?","answer":"≈ $2210.34","solution":"A = 2000e^(0.05×2) = 2000e^0.1 ≈ 2210.34."},{"type":"regular","q":"Calculate simple interest on $1800 at 2.5% for 8 years.","answer":"$360","solution":"I = 1800 × 0.025 × 8 = 360."},{"type":"word","q":"Maria invests $5000 at 4% simple interest. How much will she have after 3 years?","answer":"$5600","solution":"Interest = 5000 × 0.04 × 3 = 600; Total = 5000 + 600 = 5600."},{"type":"word","q":"A savings account offers 6% annual interest compounded annually. If you deposit $2000, what is the balance after 4 years?","answer":"≈ $2524.95","solution":"A = 2000(1.06)^4 ≈ 2524.95."},{"type":"word","q":"James borrows $1000 at 5% simple interest. How much interest will he owe after 2 years?","answer":"$100","solution":"I = 1000 × 0.05 × 2 = 100."},{"type":"word","q":"An investment grows from $4000 to $4800 in 2 years using simple interest. What is the annual interest rate?","answer":"10%","solution":"Interest earned = 800; 800 = 4000 × r × 2, so r = 0.10 or 10%."},{"type":"word","q":"A bank offers 3% interest compounded quarterly. If you invest $3000, what will you have after 3 years?","answer":"≈ $3279.13","solution":"A = 3000(1 + 0.03/4)^(4×3) = 3000(1.0075)^12 ≈ 3279.13."},{"type":"word","q":"Sarah deposits $1500 in an account with continuous compounding at 4.5% annual rate. What is the amount after 5 years?","answer":"≈ $1888.64","solution":"A = 1500e^(0.045×5) = 1500e^0.225 ≈ 1888.64."}]);
  add("finitemath", "fm5", 1, [{"type":"regular","q":"Using the ordinary annuity formula, find the future value of $200 payments made annually for 5 years at 5% interest.","answer":"≈ $1157.63","solution":"FV = 200 × [(1.05^5 - 1) / 0.05] = 200 × 5.5256 ≈ 1157.63."},{"type":"regular","q":"Calculate the future value of an ordinary annuity: $300/month for 24 months at 6% annual interest (0.5% monthly).","answer":"≈ $7,414.59","solution":"FV = 300 × [(1.005^24 - 1) / 0.005] ≈ 7414.59."},{"type":"regular","q":"What is the future value of $500 quarterly payments for 3 years at 8% annual interest (2% quarterly)?","answer":"≈ $6,624.88","solution":"FV = 500 × [(1.02^12 - 1) / 0.02] ≈ 6624.88."},{"type":"regular","q":"An annuity has $150 annual payments for 10 years at 4% interest. Find the future value.","answer":"≈ $1,800.94","solution":"FV = 150 × [(1.04^10 - 1) / 0.04] ≈ 1800.94."},{"type":"regular","q":"Calculate FV for $250 semi-annual payments over 4 years at 6% annual (3% semi-annual) interest.","answer":"≈ $2,186.24","solution":"FV = 250 × [(1.03^8 - 1) / 0.03] ≈ 2186.24."},{"type":"regular","q":"If you deposit $100 per month for 36 months at 3% annual (0.25% monthly), what is the future value?","answer":"≈ $3,681.41","solution":"FV = 100 × [(1.0025^36 - 1) / 0.0025] ≈ 3681.41."},{"type":"regular","q":"Find the future value of an annuity with $75 quarterly payments for 5 years at 5% annual (1.25% quarterly) interest.","answer":"≈ $1,605.39","solution":"FV = 75 × [(1.0125^20 - 1) / 0.0125] ≈ 1605.39."},{"type":"regular","q":"Calculate the future value of $400 annual payments for 7 years at 3.5% interest.","answer":"≈ $3,066.48","solution":"FV = 400 × [(1.035^7 - 1) / 0.035] ≈ 3066.48."},{"type":"regular","q":"What is the future value of $50 monthly payments for 60 months at 4.8% annual (0.4% monthly) interest?","answer":"≈ $3,186.62","solution":"FV = 50 × [(1.004^60 - 1) / 0.004] ≈ 3186.62."},{"type":"word","q":"A retirement plan requires $500 annual contributions for 20 years at 6% interest. What is the future value?","answer":"≈ $18,585.54","solution":"FV = 500 × [(1.06^20 - 1) / 0.06] ≈ 18585.54."},{"type":"word","q":"You save $200 every quarter for 6 years in an account earning 5% annual (1.25% quarterly) interest. What will you have?","answer":"≈ $5,314.63","solution":"FV = 200 × [(1.0125^24 - 1) / 0.0125] ≈ 5314.63."},{"type":"word","q":"A college fund receives $1000 annual deposits for 18 years at 7% interest. Calculate the future value.","answer":"≈ $34,999.27","solution":"FV = 1000 × [(1.07^18 - 1) / 0.07] ≈ 34999.27."},{"type":"word","q":"You contribute $150 monthly to a savings plan for 10 years at 4.2% annual (0.35% monthly) interest. What is the final amount?","answer":"≈ $20,245.77","solution":"FV = 150 × [(1.0035^120 - 1) / 0.0035] ≈ 20245.77."},{"type":"word","q":"A business saves $2000 semi-annually for 8 years at 5.5% annual (2.75% semi-annual) interest. What is the future value?","answer":"≈ $36,873.48","solution":"FV = 2000 × [(1.0275^16 - 1) / 0.0275] ≈ 36873.48."},{"type":"word","q":"If you deposit $75 every month for 15 years in an account earning 3.6% annual (0.3% monthly) interest, how much will you accumulate?","answer":"≈ $15,497.94","solution":"FV = 75 × [(1.003^180 - 1) / 0.003] ≈ 15497.94."}]);
  add("finitemath", "fm5", 2, [{"type":"regular","q":"Find the present value of $5000 due in 3 years at 6% annual interest.","answer":"≈ $3,969.91","solution":"PV = 5000 / (1.06)^3 ≈ 3969.91."},{"type":"regular","q":"Calculate the present value of $2000 due in 4 years at 5% interest.","answer":"≈ $1,644.56","solution":"PV = 2000 / (1.05)^4 ≈ 1644.56."},{"type":"regular","q":"What is the present value of $8000 due in 2 years at 7% annual interest?","answer":"≈ $6,994.17","solution":"PV = 8000 / (1.07)^2 ≈ 6994.17."},{"type":"regular","q":"Find PV of $3000 due in 5 years at 4% interest.","answer":"≈ $2,465.69","solution":"PV = 3000 / (1.04)^5 ≈ 2465.69."},{"type":"regular","q":"Calculate the present value of $10,000 due in 6 years at 3.5% interest.","answer":"≈ $8,050.38","solution":"PV = 10000 / (1.035)^6 ≈ 8050.38."},{"type":"regular","q":"What is the present value of $1500 due in 18 months at 5% annual interest?","answer":"≈ $1,395.35","solution":"PV = 1500 / (1.05)^1.5 ≈ 1395.35."},{"type":"regular","q":"Find the PV of $6000 due in 4 years at 8% interest.","answer":"≈ $4,409.73","solution":"PV = 6000 / (1.08)^4 ≈ 4409.73."},{"type":"regular","q":"Calculate PV of $4500 due in 3 years at 6.5% interest.","answer":"≈ $3,704.45","solution":"PV = 4500 / (1.065)^3 ≈ 3704.45."},{"type":"regular","q":"What is the present value of $12,000 due in 7 years at 4.5% interest?","answer":"≈ $9,049.88","solution":"PV = 12000 / (1.045)^7 ≈ 9049.88."},{"type":"word","q":"You need $10,000 in 5 years. How much should you invest today at 5% interest?","answer":"≈ $7,835.26","solution":"PV = 10000 / (1.05)^5 ≈ 7835.26."},{"type":"word","q":"A bond will pay $5000 in 8 years. If the discount rate is 6%, what is its present value?","answer":"≈ $3,147.45","solution":"PV = 5000 / (1.06)^8 ≈ 3147.45."},{"type":"word","q":"An investment promises $20,000 in 10 years. At a 4% discount rate, what is the present value?","answer":"≈ $13,513.30","solution":"PV = 20000 / (1.04)^10 ≈ 13513.30."},{"type":"word","q":"A loan of $2500 is due in 2 years. If the interest rate is 7%, what is the present value?","answer":"≈ $2,177.71","solution":"PV = 2500 / (1.07)^2 ≈ 2177.71."},{"type":"word","q":"You are offered $15,000 in 6 years. How much is that worth today at 5.5% interest?","answer":"≈ $11,070.97","solution":"PV = 15000 / (1.055)^6 ≈ 11070.97."},{"type":"word","q":"A company will receive $50,000 in 3 years. At a 6.5% discount rate, what is the present value of this payment?","answer":"≈ $40,803.46","solution":"PV = 50000 / (1.065)^3 ≈ 40803.46."}]);
  addCum("finitemath", "fm5", [{"type":"regular","q":"Calculate simple interest: $2500 at 4% for 3 years.","answer":"$300","solution":"I = Prt = 2500 × 0.04 × 3 = 300."},{"type":"regular","q":"Find the compound amount: $1800 at 5% annual, compounded semi-annually, for 2 years.","answer":"≈ $1,987.73","solution":"A = 1800(1 + 0.05/2)^(2×2) = 1800(1.025)^4 ≈ 1987.73."},{"type":"regular","q":"What is the continuous compound amount for $2200 at 3.5% for 4 years?","answer":"≈ $2,588.92","solution":"A = 2200e^(0.035×4) = 2200e^0.14 ≈ 2588.92."},{"type":"regular","q":"Calculate the future value of an ordinary annuity: $250 annual payments for 6 years at 5% interest.","answer":"≈ $1,637.84","solution":"FV = 250 × [(1.05^6 - 1) / 0.05] ≈ 1637.84."},{"type":"regular","q":"Find the present value of $7000 due in 5 years at 6% interest.","answer":"≈ $5,234.26","solution":"PV = 7000 / (1.06)^5 ≈ 5234.26."},{"type":"regular","q":"What is the total amount for $3000 at 6% simple interest for 2.5 years?","answer":"$3,450","solution":"I = 3000 × 0.06 × 2.5 = 450; Total = 3000 + 450 = 3450."},{"type":"regular","q":"Calculate the compound amount: $900 at 4% annual, compounded quarterly, for 3 years.","answer":"≈ $1,014.67","solution":"A = 900(1 + 0.04/4)^(4×3) = 900(1.01)^12 ≈ 1014.67."},{"type":"regular","q":"Find the future value of $150 monthly payments for 24 months at 4.8% annual (0.4% monthly) interest.","answer":"≈ $3,754.50","solution":"FV = 150 × [(1.004^24 - 1) / 0.004] ≈ 3754.50."},{"type":"regular","q":"What is the present value of $4500 due in 3 years at 5.5% interest?","answer":"≈ $3,833.28","solution":"PV = 4500 / (1.055)^3 ≈ 3833.28."},{"type":"regular","q":"Calculate simple interest earned on $1200 at 3.5% for 18 months.","answer":"$63","solution":"I = 1200 × 0.035 × 1.5 = 63."},{"type":"regular","q":"Find the continuous compound amount for $1600 at 5% for 2 years.","answer":"≈ $1,769.04","solution":"A = 1600e^(0.05×2) = 1600e^0.1 ≈ 1769.04."},{"type":"regular","q":"Calculate the FV of $300 quarterly payments for 4 years at 6% annual (1.5% quarterly) interest.","answer":"≈ $5,155.41","solution":"FV = 300 × [(1.015^16 - 1) / 0.015] ≈ 5155.41."},{"type":"regular","q":"What is the PV of $9000 due in 4 years at 7% interest?","answer":"≈ $6,872.74","solution":"PV = 9000 / (1.07)^4 ≈ 6872.74."},{"type":"regular","q":"Find the compound amount: $2000 at 3% annual, compounded monthly, for 5 years.","answer":"≈ $2,323.65","solution":"A = 2000(1 + 0.03/12)^(12×5) = 2000(1.0025)^60 ≈ 2323.65."},{"type":"word","q":"A savings account earns 5% simple interest. If you deposit $4000, how much interest will you earn in 4 years?","answer":"$800","solution":"I = 4000 × 0.05 × 4 = 800."},{"type":"word","q":"You invest $3000 at 6% compounded annually. What will you have after 3 years?","answer":"≈ $3,573.05","solution":"A = 3000(1.06)^3 ≈ 3573.05."},{"type":"word","q":"A retirement account receives $500 annual contributions for 15 years at 5% interest. What is the future value?","answer":"≈ $11,385.66","solution":"FV = 500 × [(1.05^15 - 1) / 0.05] ≈ 11385.66."},{"type":"word","q":"You need $8000 in 4 years. How much should you invest today at 4.5% interest?","answer":"≈ $6,707.17","solution":"PV = 8000 / (1.045)^4 ≈ 6707.17."},{"type":"word","q":"An investment grows continuously at 4% per year. If you invest $2500, what will you have after 6 years?","answer":"≈ $3,174.23","solution":"A = 2500e^(0.04×6) = 2500e^0.24 ≈ 3174.23."},{"type":"word","q":"You save $200 every month for 5 years in an account earning 3.6% annual (0.3% monthly) interest. What is the final amount?","answer":"≈ $12,582.34","solution":"FV = 200 × [(1.003^60 - 1) / 0.003] ≈ 12582.34."},{"type":"word","q":"A bond will pay $6000 in 7 years. If the discount rate is 5%, what is its present value today?","answer":"≈ $4,263.97","solution":"PV = 6000 / (1.05)^7 ≈ 4263.97."},{"type":"word","q":"Sarah deposits $1000 at 5% compounded quarterly. How much will she have after 2 years?","answer":"≈ $1,104.49","solution":"A = 1000(1 + 0.05/4)^(4×2) = 1000(1.0125)^8 ≈ 1104.49."},{"type":"word","q":"A company contributes $1000 semi-annually to a fund for 10 years at 5.5% annual (2.75% semi-annual) interest. What is the future value?","answer":"≈ $25,046.79","solution":"FV = 1000 × [(1.0275^20 - 1) / 0.0275] ≈ 25046.79."},{"type":"word","q":"An investment opportunity offers $12,000 in 5 years. At a 6.5% discount rate, what is the present value?","answer":"≈ $8,873.62","solution":"PV = 12000 / (1.065)^5 ≈ 8873.62."}]);
